package internal

import (
	"errors"
	"testing"
)

// Note: Tests on this file are generated by LLM. I have checked
// each of these tests one by one but I still feel the need to
// mention this as a disclaimer
// --- NewFieldSelector tests ---

func TestNewFieldSelector_EmptyString(t *testing.T) {
	_, err := NewFieldSelector("")
	if !errors.Is(err, ErrFieldStrEmpty) {
		t.Errorf("expected ErrFieldStrEmpty, got %v", err)
	}
}

func TestNewFieldSelector_SingleField(t *testing.T) {
	fs, err := NewFieldSelector("1")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(fs.sorted) != 1 || fs.sorted[0] != 1 {
		t.Errorf("expected sorted=[1], got %v", fs.sorted)
	}
	if fs.maxField != 1 {
		t.Errorf("expected maxField=1, got %d", fs.maxField)
	}
}

func TestNewFieldSelector_MultipleFields(t *testing.T) {
	fs, err := NewFieldSelector("3,1,2")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	expected := []int{1, 2, 3}
	for i, v := range fs.sorted {
		if v != expected[i] {
			t.Errorf("expected sorted=%v, got %v", expected, fs.sorted)
			break
		}
	}
	if fs.maxField != 3 {
		t.Errorf("expected maxField=3, got %d", fs.maxField)
	}
}

func TestNewFieldSelector_FieldZero(t *testing.T) {
	_, err := NewFieldSelector("0")
	if !errors.Is(err, ErrFieldBelowOne) {
		t.Errorf("expected ErrFieldBelowOne, got %v", err)
	}
}

func TestNewFieldSelector_NegativeField(t *testing.T) {
	_, err := NewFieldSelector("-1")
	if !errors.Is(err, ErrFieldBelowOne) {
		t.Errorf("expected ErrFieldBelowOne, got %v", err)
	}
}

func TestNewFieldSelector_InvalidFieldNonNumeric(t *testing.T) {
	_, err := NewFieldSelector("a")
	if err == nil {
		t.Error("expected error for non-numeric field, got nil")
	}
}

