func TestNewFieldSelector_ValidRange(t *testing.T) {
	fs, err := NewFieldSelector("1-3")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	expected := []int{1, 2, 3}
	for i, v := range fs.sorted {
		if v != expected[i] {
			t.Errorf("expected sorted=%v, got %v", expected, fs.sorted)
			break
		}
	}
	if fs.maxField != 3 {
		t.Errorf("expected maxField=3, got %d", fs.maxField)
	}
}

func TestNewFieldSelector_SingleValueRange(t *testing.T) {
	// "3-3" is a degenerate but valid range
	fs, err := NewFieldSelector("3-3")
	if err != nil {
		t.Fatalf("expected no error for single-value range, got %v", err)
	}
	if len(fs.sorted) != 1 || fs.sorted[0] != 3 {
		t.Errorf("expected sorted=[3], got %v", fs.sorted)
	}
}

func TestNewFieldSelector_RangeStartGreaterThanEnd(t *testing.T) {
	_, err := NewFieldSelector("3-1")
	if !errors.Is(err, ErrInvalidRange) {
		t.Errorf("expected ErrInvalidRange, got %v", err)
	}
}

