// --- Mixed fields and ranges ---

func TestNewFieldSelector_MixedFieldsAndRanges(t *testing.T) {
	fs, err := NewFieldSelector("1,3-5,7")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	expected := []int{1, 3, 4, 5, 7}
	for i, v := range fs.sorted {
		if v != expected[i] {
			t.Errorf("expected sorted=%v, got %v", expected, fs.sorted)
			break
		}
	}
	if fs.maxField != 7 {
		t.Errorf("expected maxField=7, got %d", fs.maxField)
	}
}

func TestNewFieldSelector_MaxFieldTrackedAcrossMixed(t *testing.T) {
	fs, err := NewFieldSelector("2-4,1")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if fs.maxField != 4 {
		t.Errorf("expected maxField=4, got %d", fs.maxField)
	}
}

// --- Extract tests ---

func TestExtract_SingleField(t *testing.T) {
	fs, _ := NewFieldSelector("1")
	got, err := fs.Extract("a:b:c", ":")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if got != "a" {
		t.Errorf("expected 'a', got %q", got)
	}
}

func TestExtract_OneIndexed(t *testing.T) {
	// field 1 must return first word, not second
	fs, _ := NewFieldSelector("1")
	got, err := fs.Extract("first:second:third", ":")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if got != "first" {
		t.Errorf("expected 'first', got %q", got)
	}
}

func TestExtract_MultipleFields(t *testing.T) {
	fs, _ := NewFieldSelector("1,3")
	got, err := fs.Extract("a:b:c", ":")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if got != "a:c" {
		t.Errorf("expected 'a:c', got %q", got)
	}
}

func TestExtract_Range(t *testing.T) {
	fs, _ := NewFieldSelector("1-3")
	got, err := fs.Extract("a:b:c:d", ":")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if got != "a:b:c" {
		t.Errorf("expected 'a:b:c', got %q", got)
	}
}

func TestExtract_LastField(t *testing.T) {
	// field == len(words) is valid with 1-indexing
	fs, _ := NewFieldSelector("3")
	got, err := fs.Extract("a:b:c", ":")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if got != "c" {
		t.Errorf("expected 'c', got %q", got)
	}
}

func TestExtract_FieldOutOfBounds(t *testing.T) {
	fs, _ := NewFieldSelector("5")
	_, err := fs.Extract("a:b:c", ":")
	if !errors.Is(err, ErrFieldOutOfBounds) {
		t.Errorf("expected ErrFieldOutOfBounds, got %v", err)
	}
}

func TestExtract_DifferentDelimiter(t *testing.T) {
	fs, _ := NewFieldSelector("2")
	got, err := fs.Extract("a,b,c", ",")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if got != "b" {
		t.Errorf("expected 'b', got %q", got)
	}
}

func TestExtract_OutputJoinedByDelimiter(t *testing.T) {
	fs, _ := NewFieldSelector("1,3")
	got, err := fs.Extract("a,b,c", ",")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if got != "a,c" {
		t.Errorf("expected 'a,c', got %q", got)
	}
}

func TestExtract_SortedOutputRegardlessOfInputOrder(t *testing.T) {
	// fields stored sorted, so output order is always ascending
	fs, _ := NewFieldSelector("3,1")
	got, err := fs.Extract("a:b:c", ":")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if got != "a:c" {
		t.Errorf("expected 'a:c', got %q", got)
	}
}
